import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { OxlintNode } from '@teambit/oxc.linter.oxlint-node';

const currentFile = fileURLToPath(import.meta.url);

describe('OxlintNode integration', () => {
  it('uses the current Oxlint release', () => {
    expect(OxlintNode.create().version()).toBe('Version: 1.79.0');
  });

  it('returns structured JSON diagnostics', async () => {
    const result = await OxlintNode.create({ formats: ['json'] }).run([
      currentFile,
    ]);

    expect(result.json?.number_of_files).toBe(1);
    expect(result.json?.diagnostics).toEqual(expect.any(Array));
  });

  it('supports unmatched paths without treating them as a process failure', async () => {
    const result = await OxlintNode.create({
      formats: ['json'],
      noErrorOnUnmatchedPattern: true,
    }).run(['/definitely/missing/oxlint-file.ts']);

    expect(result.json?.number_of_files).toBe(0);
    expect(result.json?.diagnostics).toEqual([]);
  });

  it('maps plugins, rules, fixes, and runtime options to CLI arguments', () => {
    const oxlint = OxlintNode.create({
      formats: ['agent'],
      pluginsFlags: { react: true, unicorn: false },
      rulesFlags: [{ name: 'suspicious', severity: 'deny' }],
      fixesFlags: { suggestions: true },
      noErrorOnUnmatchedPattern: true,
    });

    expect(oxlint.toCliArgs('agent', ['src/index.ts'])).toEqual(
      expect.arrayContaining([
        'src/index.ts',
        '--react-plugin',
        '--disable-unicorn-plugin',
        '--deny=suspicious',
        '--fix-suggestions',
        '--no-error-on-unmatched-pattern',
        '--format=agent',
      ])
    );
  });

  it('throws a readable error when Oxlint returns non-JSON output', async () => {
    const oxlint = OxlintNode.create({
      binPath: process.execPath,
      formats: ['json'],
    });

    await expect(
      oxlint.run(['--eval', 'process.stdout.write("not json")', '--'])
    ).rejects.toThrow('oxlint returned non-JSON output (exit code 0):\nnot json');
  });

  it('runs a Node.js shebang bin through Node.js (Windows cannot execute it directly)', async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'oxlint-node-'));
    // No extension and no execute permission, like `oxlint/bin/oxlint` on Windows.
    const binPath = path.join(tmpDir, 'fake-oxlint');
    fs.writeFileSync(
      binPath,
      '#!/usr/bin/env node\nprocess.stdout.write(JSON.stringify({ diagnostics: [], number_of_files: 7, number_of_rules: 0, threads_count: 0, start_time: 0 }));\n',
      { mode: 0o644 }
    );
    try {
      const result = await OxlintNode.create({ binPath, formats: ['json'] }).run([
        currentFile,
      ]);
      expect(result.json?.number_of_files).toBe(7);
    } finally {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });

  it('includes stderr when the Oxlint process fails with empty stdout', async () => {
    const oxlint = OxlintNode.create({
      binPath: process.execPath,
      formats: ['json'],
      noErrorOnUnmatchedPattern: true,
    });

    await expect(
      oxlint.run([
        '--eval',
        'process.stderr.write("Cannot find native binding"); process.exit(1)',
        '--',
      ])
    ).rejects.toThrow(
      'oxlint returned non-JSON output (exit code 1):\n\nstderr:\nCannot find native binding'
    );
  });
});
